// src/core/root-config/root-config.routes.ts
import { FastifyPluginAsync } from 'fastify';
import { rootConfigService } from './root-config.service';
import {
  updateRootConfigSchema,
  setRegionSchema,
  setLanguagesSchema,
  setTimezoneSchema,
  setCurrencySchema,
} from './root-config.schemas';

const rootConfigRoutes: FastifyPluginAsync = async (fastify) => {
  /**
   * GET /root-config
   * Busca a configuração-raiz atual
   */
  fastify.get('/', async () => {
    const config = await rootConfigService.getConfig();
    return config || {
      id: null,
      countryId: null,
      stateId: null,
      cityId: null,
      timezone: null,
      currency: null,
      languages: [],
      createdAt: new Date(),
      updatedAt: new Date(),
    };
  });

  /**
   * POST /root-config/update
   * Atualiza a configuração-raiz
   */
  fastify.post<{
    Body: {
      countryId?: string | null;
      stateId?: string | null;
      cityId?: string | null;
      timezone?: string | null;
      currency?: string | null;
      languages?: string[];
    };
  }>(
    '/update',
    {
      schema: {
        body: {
          type: 'object',
          properties: {
            countryId: { type: ['string', 'null'] },
            stateId: { type: ['string', 'null'] },
            cityId: { type: ['string', 'null'] },
            timezone: { type: ['string', 'null'] },
            currency: { type: ['string', 'null'] },
            languages: { type: 'array', items: { type: 'string' } },
          },
        },
      },
    },
    async (req, reply) => {
      try {
        const validated = updateRootConfigSchema.parse(req.body);
        const config = await rootConfigService.updateConfig(validated);
        return reply.status(200).send(config);
      } catch (error) {
        if (error instanceof Error) {
          return reply.status(400).send({ error: error.message });
        }
        return reply.status(500).send({ error: 'Erro ao atualizar configuração' });
      }
    }
  );

  /**
   * POST /root-config/set-region
   * Define a região (país, estado, cidade)
   */
  fastify.post<{
    Body: {
      countryId?: string | null;
      stateId?: string | null;
      cityId?: string | null;
    };
  }>(
    '/set-region',
    {
      schema: {
        body: {
          type: 'object',
          properties: {
            countryId: { type: ['string', 'null'] },
            stateId: { type: ['string', 'null'] },
            cityId: { type: ['string', 'null'] },
          },
        },
      },
    },
    async (req, reply) => {
      try {
        const validated = setRegionSchema.parse(req.body);
        const config = await rootConfigService.setRegion(
          validated.countryId,
          validated.stateId,
          validated.cityId
        );
        return reply.status(200).send(config);
      } catch (error) {
        if (error instanceof Error) {
          return reply.status(400).send({ error: error.message });
        }
        return reply.status(500).send({ error: 'Erro ao definir região' });
      }
    }
  );

  /**
   * POST /root-config/set-timezone
   * Define o timezone
   */
  fastify.post<{
    Body: {
      timezone: string;
    };
  }>(
    '/set-timezone',
    {
      schema: {
        body: {
          type: 'object',
          required: ['timezone'],
          properties: {
            timezone: { type: 'string' },
          },
        },
      },
    },
    async (req, reply) => {
      try {
        const validated = setTimezoneSchema.parse(req.body);
        const config = await rootConfigService.setTimezone(validated.timezone);
        return reply.status(200).send(config);
      } catch (error) {
        if (error instanceof Error) {
          return reply.status(400).send({ error: error.message });
        }
        return reply.status(500).send({ error: 'Erro ao definir timezone' });
      }
    }
  );

  /**
   * POST /root-config/set-currency
   * Define a moeda
   */
  fastify.post<{
    Body: {
      currency: string;
    };
  }>(
    '/set-currency',
    {
      schema: {
        body: {
          type: 'object',
          required: ['currency'],
          properties: {
            currency: { type: 'string' },
          },
        },
      },
    },
    async (req, reply) => {
      try {
        const validated = setCurrencySchema.parse(req.body);
        const config = await rootConfigService.setCurrency(validated.currency);
        return reply.status(200).send(config);
      } catch (error) {
        if (error instanceof Error) {
          return reply.status(400).send({ error: error.message });
        }
        return reply.status(500).send({ error: 'Erro ao definir moeda' });
      }
    }
  );

  /**
   * POST /root-config/set-languages
   * Define os idiomas
   */
  fastify.post<{
    Body: {
      languages: string[];
    };
  }>(
    '/set-languages',
    {
      schema: {
        body: {
          type: 'object',
          required: ['languages'],
          properties: {
            languages: {
              type: 'array',
              items: { type: 'string' },
            },
          },
        },
      },
    },
    async (req, reply) => {
      try {
        const validated = setLanguagesSchema.parse(req.body);
        const config = await rootConfigService.setLanguages(validated.languages);
        return reply.status(200).send(config);
      } catch (error) {
        if (error instanceof Error) {
          return reply.status(400).send({ error: error.message });
        }
        return reply.status(500).send({ error: 'Erro ao definir idiomas' });
      }
    }
  );
};

export default rootConfigRoutes;
















